create or replace function app.phase2_is_team(p_patient uuid,p_kind text default null) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.care_team_assignments where org_id=app.org_id() and patient_id=p_patient and staff_member_id=app.phase2_staff_id() and starts_at<=now() and (ends_at is null or now()<ends_at) and (p_kind is null or assignment_kind=p_kind)) $$;
create or replace function app.chart_entry(p_patient uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare r text:=app.current_role(); s uuid:=app.phase2_staff_id(); site uuid; team boolean; restricted boolean; opened boolean; begin
if s is null or r is null or r not in ('physician','pmhnp','nurse_rn','lvn','therapist','sud_counselor','clinical_trainee','medical_assistant','ecm_provider','cf_care_manager','peer_specialist','community_health_worker','clinical_coordinator') then return jsonb_build_object('ok',false,'reason','role'); end if;
if not exists(select 1 from public.patients where org_id=app.org_id() and id=p_patient) then return jsonb_build_object('ok',false,'reason','missing'); end if;
select site_id into site from public.patient_site_enrollments where org_id=app.org_id() and patient_id=p_patient and starts_at<=now() and (ends_at is null or now()<ends_at) order by starts_at desc,id limit 1;
if site is null or not exists(select 1 from public.staff_site_assignments where org_id=app.org_id() and staff_member_id=s and site_id=site and starts_at<=now() and (ends_at is null or now()<ends_at)) then return jsonb_build_object('ok',false,'reason','site'); end if;
team:=app.phase2_is_team(p_patient); restricted:=app.phase2_restricted(p_patient);
opened:=exists(select 1 from public.restricted_record_opens o join public.acting_role_sessions rs on rs.id=o.acting_session_id and rs.org_id=o.org_id where o.patient_id=p_patient and o.account_id=app.account_id() and o.org_id=app.org_id() and rs.ended_at is null and rs.role=r);
return jsonb_build_object('ok',not restricted or team or opened,'entryEligible',true,'restricted',restricted,'careTeam',team,'outsideCaseload',not team,'searchable',not restricted or team,'reason',case when restricted and not team and not opened then 'Restricted record — reason required' else null end); end $$;
create or replace function app.phase2_packet_access(p_referral uuid,p_part2 boolean) returns boolean language plpgsql stable security definer set search_path='' as $$ declare p uuid; begin
select linked_patient_id into p from public.referrals where id=p_referral and org_id=app.org_id();
if app.phase2_intake(p_referral,true) then return not p_part2 or app.phase2_treatment_consent(p); end if;
return p is not null and exists(select 1 from public.intake_checklists where org_id=app.org_id() and referral_id=p_referral and completed_at is not null) and (app.phase2_is_team(p,'care_manager') or app.phase2_is_team(p,'clinician')) and app.phase2_chart_read(p,'documents') and (not p_part2 or exists(select 1 from app.can_access('sud_treatment',p) where level<>'none')); end $$;
revoke execute on function public.chart_reason_open(uuid,text,text),public.clinician_coverage_set(uuid,uuid,timestamptz,timestamptz) from public,anon,authenticated,service_role;
revoke execute on function app.group_context_allowed(uuid,text),app.intake_packet_window(uuid) from public,anon,authenticated,service_role;
comment on function app.chart_entry(uuid) is 'Previous app-matching rule restored at 28 Oct access batch stop: Part 2 matrix conflict unresolved; candidate read policies remain closed';
notify pgrst,'reload schema';